// Generated by Cypress Author on 2026-11-10.
// Editing an event as its organizer, including one that has already started.
import { buildEvent, buildUser, minutesFromNow } from "../support/data";

describe("Editing an event", () => {
  const organizer = buildUser({ role: "ORGANIZER" });

  beforeEach(() => {
    cy.stubApi(organizer);
    // The events list the form returns to after saving
    cy.intercept("GET", "/api/events?*", { body: [] });
    cy.intercept("GET", "/api/events", { body: [] });
  });

  /** Opens the edit form for `event` and waits for it to load */
  function openEditForm(event: ReturnType<typeof buildEvent>) {
    cy.intercept("GET", `/api/events/${event.id}`, { body: event }).as("event");
    cy.visitSignedIn(`/events/${event.id}/edit`, organizer);
    cy.wait("@event");
    cy.get("#ev-title").should("have.value", event.title);
  }

  it("fixing the description of an event that already started → saves it with the start time unchanged", () => {
    const started = buildEvent({ startsAt: minutesFromNow(-60), description: "Room SC1001" });
    openEditForm(started);
    cy.intercept("PUT", `/api/events/${started.id}`, (req) => req.reply({ body: { ...started, ...req.body } })).as("save");

    cy.get("#ev-description").clear().type("Moved to room SC2002");
    cy.contains("button", "Save changes").click();

    cy.wait("@save").its("request.body").then((body) => {
      expect(body.description).to.eq("Moved to room SC2002");
      // Same instant, even though the form sends it with a time-zone offset
      expect(Date.parse(body.startsAt)).to.eq(Date.parse(started.startsAt));
    });
    cy.location("pathname").should("eq", "/events");
    cy.contains("Event updated.").should("be.visible");
  });

  it("moving an event's start into the past → shows an error and does not save", () => {
    const upcoming = buildEvent({ startsAt: minutesFromNow(24 * 60) });
    openEditForm(upcoming);
    cy.intercept("PUT", `/api/events/${upcoming.id}`, cy.spy().as("saveCall"));

    cy.get("#ev-date").clear().type("2020-01-01");
    cy.contains("button", "Save changes").click();

    cy.contains("The event must start in the future.").should("be.visible");
    cy.get("@saveCall").should("not.have.been.called");
    cy.location("pathname").should("eq", `/events/${upcoming.id}/edit`);
  });
});
